-- Store six teacher-editable comprehension prompts with each story.
-- Existing content, selection settings, teacher ownership and RLS stay intact.
BEGIN;
SET LOCAL lock_timeout = '5s';
ALTER TABLE public.assessment_content DROP CONSTRAINT IF EXISTS assessment_content_category_check;
ALTER TABLE public.assessment_content ADD CONSTRAINT assessment_content_category_check
  CHECK (category IN ('letters', 'words', 'stories', 'settings', 'story_questions'));

-- Retire only the two exact shipped placeholder texts, as the existing app does.
DELETE FROM public.assessment_content WHERE category = 'stories' AND (
 (assessment_period = 'MoSY' AND story_title = 'A Morning Walk' AND content = 'The children walk together and help one another on their way to school.') OR
 (assessment_period = 'EoSY' AND story_title = 'The Kind Child' AND content = 'A kind child notices someone who needs help and chooses to lend a hand.')
);

-- All teachers receive the new shared defaults in empty period pools.
-- A teacher's own saved stories are never replaced by this seed.
WITH defaults(period, position, title, text, questions) AS (VALUES
('BoSY', 1, 'Para the Parrot', 'Para flies away from the houses and into the market. She must look for some fruits and food she can eat. She is having fun, but wants to go home. It is getting dark. There are many cars on the road because it is the end of the work day. Then, she sees something! Para stops flying and lands on top of a parked car. She sees a police officer and he is directing traffic. He is also dancing! Para has never seen a police officer dance. The police officer is smiling. Para wants to learn more about this man.', '{"questions":[{"text":"What must Para look for?","possibleAnswer":"Fruits or food to eat."},{"text":"What time or part of the day is it?","possibleAnswer":"Late afternoon or early evening; it is getting dark at the end of the workday."},{"text":"What does Para land on?","possibleAnswer":"The top of a parked car."},{"text":"Who does Para see?","possibleAnswer":"A police officer."},{"text":"What else is the police officer doing besides directing traffic?","possibleAnswer":"Dancing."},{"text":"What could the police officer be feeling?","possibleAnswer":"Happy, cheerful, or enjoying his work; accept a similar feeling supported by his smile and dancing."}]}'),
('BoSY', 2, 'A Day in the Fields', 'Dulnuwan is a farmer. He works in the fields everyday. His wife Bugan helps him. Ali and Dina help too when they are not in school. Today, Dulnuwan drains the water from the field and prepares the seedbed. Bugan, Ali, and Dina pull the weeds. They work all morning. They rest under the shade of a tree and eat lunch. They eat boiled rice and beans. They are proud of their work. Dulnuwan looks at the clear blue sky. There is not a cloud in sight. He looks at the terraces below. He bends to pick a handful of soil.', '{"questions":[{"text":"What is the job of Dulnuwan?","possibleAnswer":"He is a farmer."},{"text":"When do Ali and Dina help Dulnuwan and Bugan?","possibleAnswer":"When they are not in school."},{"text":"Where do they rest?","possibleAnswer":"Under the shade of a tree."},{"text":"Why do they rest?","possibleAnswer":"They have worked all morning and need a break or lunch; accept a similar supported answer."},{"text":"What kind of weather or day is it?","possibleAnswer":"Clear or sunny, with a blue sky and no clouds."},{"text":"What does Dulnuwan pick up?","possibleAnswer":"A handful of soil."}]}'),
('MoSY', 1, 'A Bird at the School Garden', 'A small bird lands beside the school garden. It hops near a row of pots and looks around. Nena sees the bird from her classroom window. The sun is warm, and the soil looks dry. She fills a shallow dish with clean water. Then she places it under a leafy tree. Nena steps back and waits quietly. The bird tilts its head before hopping toward the dish. It drinks a little water and shakes its wings. Soon, another bird joins it in the shade. Nena smiles at the two visitors. She wonders if they will return to the garden tomorrow.', '{"questions":[{"text":"Where does the small bird land?","possibleAnswer":"Beside the school garden."},{"text":"Where is Nena when she first sees the bird?","possibleAnswer":"In her classroom, looking through the window."},{"text":"What does Nena put in the dish?","possibleAnswer":"Clean water."},{"text":"Where does she place the dish?","possibleAnswer":"Under a leafy tree."},{"text":"Why does Nena step back and wait quietly?","possibleAnswer":"So the bird will feel safe enough to come closer; accept a similar supported answer."},{"text":"How might Nena feel when another bird joins the first one?","possibleAnswer":"Happy, pleased, or excited; accept a similar feeling supported by her smile."}]}'),
('MoSY', 2, 'Water for the Seedlings', 'Ben and Ana help their father in the garden. They plant small tomato seedlings beside a bamboo fence. Father makes holes while the children carry the plants. Ana holds each stem gently. Ben covers the roots with soft soil. When the sun rises higher, they stop to drink water. The seedlings need a drink too. Ben brings a pail, and Ana fills a small can. They pour water slowly around each plant. A brown frog jumps out from behind a stone. The children laugh as it hides under a leaf. Father smiles and points to the next row of seedlings.', '{"questions":[{"text":"Who helps Father in the garden?","possibleAnswer":"Ben and Ana."},{"text":"What kind of seedlings do they plant?","possibleAnswer":"Tomato seedlings."},{"text":"Where do they plant the seedlings?","possibleAnswer":"Beside a bamboo fence in the garden."},{"text":"Why do they pour water around each plant?","possibleAnswer":"The seedlings need water to grow; accept a similar supported answer."},{"text":"What jumps out from behind a stone?","possibleAnswer":"A brown frog."},{"text":"How do the children feel when they see the frog?","possibleAnswer":"Amused, happy, or surprised; accept a similar feeling supported by their laughter."}]}'),
('EoSY', 1, 'The Kite in the Mango Tree', 'Lito takes his blue kite to the open field. His sister Mila holds it while he checks the string. A gentle wind lifts the kite above their heads. They watch it dip and dance against the bright sky. Suddenly, the wind changes. The kite catches on a low branch of a mango tree. Lito stops pulling because the paper might tear. Mila finds a long stick on the ground. Together, they gently lift the string off the branch. The kite drops onto the grass without a tear. Lito thanks his sister. They move farther from the tree before trying again.', '{"questions":[{"text":"What color is Lito''s kite?","possibleAnswer":"Blue."},{"text":"Who helps Lito fly the kite?","possibleAnswer":"His sister Mila."},{"text":"Where does the kite get caught?","possibleAnswer":"On a low branch of a mango tree."},{"text":"Why does Lito stop pulling the string?","possibleAnswer":"He does not want the paper to tear."},{"text":"What does Mila use to help free the string?","possibleAnswer":"A long stick."},{"text":"Why do they move farther from the tree before trying again?","possibleAnswer":"To keep the kite from getting caught in the tree again; accept a similar supported answer."}]}'),
('EoSY', 2, 'A Basket for the Neighbors', 'Lola picks ripe guavas from the tree behind her house. Rosa helps her place the fruit in a basket. Some guavas are round, while others look like tiny pears. They wash the fruit and set aside the soft ones for lunch. There are many guavas left. Lola asks Rosa to bring a few to their neighbors. Rosa puts them in small bags and walks with her brother along the lane. At each house, they knock and wait politely. A neighbor gives them a warm smile. When they return, Lola has sliced their guavas. They sit together and enjoy the fruit.', '{"questions":[{"text":"What fruit does Lola pick?","possibleAnswer":"Ripe guavas."},{"text":"Where is the fruit tree?","possibleAnswer":"Behind Lola''s house."},{"text":"Which guavas do they set aside for lunch?","possibleAnswer":"The soft guavas."},{"text":"Who goes with Rosa to visit the neighbors?","possibleAnswer":"Her brother."},{"text":"What do the children do when they reach each house?","possibleAnswer":"They knock and wait politely."},{"text":"Why might the neighbor smile at the children?","possibleAnswer":"The neighbor is pleased or thankful for the guavas; accept a similar supported answer."}]}')
), eligible AS (
 SELECT u.id teacher_id, p.period FROM public.users u
 CROSS JOIN (VALUES ('MoSY'), ('EoSY')) p(period)
 WHERE u.role = 'teacher' AND NOT EXISTS (
  SELECT 1 FROM public.assessment_content c WHERE c.teacher_id = u.id AND c.assessment_period::text = p.period AND c.category = 'stories'
 )
)
INSERT INTO public.assessment_content (teacher_id, assessment_period, category, position, content, story_title, updated_at)
 SELECT e.teacher_id, d.period::"AssessmentPeriod", 'stories', d.position, d.text, d.title, now() FROM eligible e JOIN defaults d ON e.period = d.period
 ON CONFLICT (teacher_id, assessment_period, category, position) DO NOTHING;

