INSERT INTO public.assessment_content (teacher_id, assessment_period, category, position, content, story_title, updated_at)
 SELECT c.teacher_id, c.assessment_period, 'story_questions', c.position, d.questions, c.story_title, now()
 FROM public.assessment_content c JOIN defaults d
 ON c.assessment_period::text = d.period AND c.story_title = d.title AND c.content = d.text
 WHERE c.category = 'stories'
 ON CONFLICT (teacher_id, assessment_period, category, position) DO NOTHING;
COMMIT;
